     2→# ABOUTME: Provides semiring elements that operate on shared ParseForest structure
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Base;
     7→use Chalk::ParseForest;
     8→use Chalk::Semiring::Viterbi;
     9→use Chalk::Semiring::Composite;
    10→
    11→# SPPF (Shared Packed Parse Forest) Node Classes
    12→class Chalk::ParseForest::SymbolNode {
    13→    use overload '""' => 'to_string';
    14→
    15→    field $symbol    :param :reader;
    16→    field $start_pos :param :reader;
    17→    field $end_pos   :param :reader;
    18→    field @packed_nodes;
    19→
