    28→            next unless @existing_children == @new_children;
    29→
    30→            # Same size - check if all children are identical references
    31→            my $all_match = 1;
    32→            for my $i (0..$#existing_children) {
    33→                unless (refaddr($existing_children[$i]) == refaddr($new_children[$i])) {
    34→                    $all_match = 0;
    35→                    last;
    36→                }
    37→            }
    38→            return if $all_match;  # Found exact duplicate, don't add
    39→        }
    40→
    41→        push( @packed_nodes, $packed_node );
    42→    }
    43→
    44→    method packed_nodes() { @packed_nodes }
    45→
    46→    method to_string(@args) {
    47→        return "$symbol\[$start_pos(),$end_pos()\]";
    48→    }
    49→
    50→    method key() { "$symbol()|$start_pos()|$end_pos()" }
    51→}
    52→
    53→class Chalk::ParseForest::PackedNode {
    54→    use overload '""' => 'to_string';
    55→
    56→    field $rule :param :reader;
    57→    field @children;
    58→
    59→    method add_child($child) {
    60→        push( @children, $child );
    61→    }
    62→
    63→    method children() { @children }
    64→
    65→    method to_string(@args) {
    66→        my $rule_str     = $rule ? $rule->to_string : "terminal";
    67→        my $children_str = join( ", ", map { "$_" } @children );
    68→        return "$rule_str -> [$children_str]";
    69→    }
    70→}
    71→
    72→class Chalk::ParseForest::TerminalNode {
    73→    use overload '""' => 'to_string';
    74→
    75→    field $symbol    :param :reader;
    76→    field $start_pos :param :reader;
    77→    field $end_pos   :param :reader;
    78→
    79→    method to_string(@args) {
    80→        return "'$symbol'\[$start_pos(),$end_pos()\]";
    81→    }
    82→
    83→    method key() { "$symbol()|$start_pos()|$end_pos()" }
    84→}
    85→
    86→# Pure SPPF Element - only tracks forest structure, no scoring
    87→class Chalk::Semiring::SPPFElement :isa(Chalk::Element) {
    88→    field $sppf_node :param :reader;
    89→    field $forest    :param :reader;
    90→
    91→    method multiply( $other, $swap = undef ) {
    92→        # Create new combined SPPF node representing sequence
    93→        my $other_node = $other->sppf_node();
    94→        my $combined_node =
    95→          $forest->create_sequence_node( $sppf_node, $other_node );
    96→
    97→        return Chalk::Semiring::SPPFElement->new(
    98→            sppf_node => $combined_node,
    99→            forest    => $forest
   100→        );
   101→    }
   102→
   103→    method add( $other, $swap = undef ) {
   104→        my $self_start = $sppf_node->start_pos();
   105→        my $self_end = $sppf_node->end_pos();
   106→        my $other_node = $other->sppf_node();
   107→        my $other_start = $other_node->start_pos();
   108→        my $other_end = $other_node->end_pos();
   109→
   110→        # Merge alternatives if they span the same range
   111→        if ($self_start == $other_start && $self_end == $other_end) {
   112→            $forest->add_alternative( $sppf_node, $other_node );
   113→        }
   114→
   115→        # Prefer element that went further (for consistency with composite pattern)
   116→        # This allows SPPF to work correctly when composed with scoring semirings
   117→        return $self_end >= $other_end ? $self : $other;
   118→    }
   119→
   120→    method equals( $other, $swap = undef ) {
   121→        return 0 unless ref($other) eq ref($self);
   122→        # Two SPPF elements are equal if they reference the same node
   123→        my $other_node = $other->sppf_node();
   124→        return refaddr($sppf_node) == refaddr($other_node);
   125→    }
   126→
   127→    method to_string(@args) {
   128→        return "SPPF:$sppf_node";
   129→    }
   130→}
   131→
   132→# Pure SPPF Semiring - only forest tracking, no Viterbi scoring
   133→class Chalk::Semiring::SPPF :isa(Chalk::Semiring) {
   134→    field $forest :reader;
   135→    field $root_element :reader;
   136→    field $mul_id :reader;
   137→    field $add_id :reader;
   138→
   139→    ADJUST {
   140→        $forest = Chalk::ParseForest->new();
   141→
   142→        $root_element = Chalk::Semiring::SPPFElement->new(
   143→            sppf_node => $forest->get_or_create_symbol_node( "ROOT", 0, 0 ),
   144→            forest    => $forest
   145→        );
   146→
   147→        $mul_id = Chalk::Semiring::SPPFElement->new(
   148→            sppf_node => $forest->get_or_create_symbol_node( "ε", 0, 0 ),
   149→            forest    => $forest
   150→        );
   151→
   152→        $add_id = Chalk::Semiring::SPPFElement->new(
   153→            sppf_node => $forest->get_or_create_symbol_node( "⊥", 0, 0 ),
   154→            forest    => $forest
   155→        );
   156→    }
   157→
   158→    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
   159→        my $lhs = $rule->lhs();
   160→        my $symbol_node =
   161→          $forest->get_or_create_symbol_node( $lhs, $start_pos, $end_pos );
   162→
   163→        return Chalk::Semiring::SPPFElement->new(
   164→            sppf_node => $symbol_node,
   165→            forest    => $forest
   166→        );
   167→    }
   168→}
   169→
   170→# SPPFViterbi Element - now a wrapper around Composite(SPPF, Viterbi)
   171→# Provides backward compatibility with previous SPPFViterbiElement API
   172→class Chalk::Semiring::SPPFViterbiElement :isa(Chalk::Element) {
   173→    field $composite :param :reader;
   174→
   175→    # Convenience accessors for backward compatibility
   176→    method score() {
   177→        return $composite->element_at(1)->score();
   178→    }
   179→
   180→    method path() {
   181→        return $composite->element_at(1)->path();
   182→    }
   183→
   184→    method sppf_node() {
   185→        return $composite->element_at(0)->sppf_node();
   186→    }
   187→
   188→    method forest() {
   189→        return $composite->element_at(0)->forest();
   190→    }
   191→
   192→    # Delegate core operations to composite
   193→    method multiply( $other, $swap = undef ) {
   194→        my $other_composite = $other->composite();
   195→        my $result = $composite->multiply($other_composite);
   196→        return Chalk::Semiring::SPPFViterbiElement->new(
   197→            composite => $result
   198→        );
   199→    }
   200→
   201→    method add( $other, $swap = undef ) {
   202→        my $other_composite = $other->composite();
   203→        my $result = $composite->add($other_composite);
   204→        return Chalk::Semiring::SPPFViterbiElement->new(
   205→            composite => $result
   206→        );
   207→    }
   208→
   209→    method equals( $other, $swap = undef ) {
   210→        return 0 unless ref($other) eq ref($self);
   211→        my $other_composite = $other->composite();
   212→        return $composite->equals($other_composite);
   213→    }
   214→
   215→    method to_string(@args) {
   216→        my $score = $self->score();
   217→        my $path = $self->path();
   218→        my $node = $self->sppf_node();
   219→        return sprintf( '%.4f[%s] SPPF:%s',
   220→            exp($score), join( ',', $path->@* ), $node );
   221→    }
   222→
   223→    # Backward compatibility helpers
   224→    method probability() {
   225→        my $score = $self->score();
   226→        return exp($score);
   227→    }
   228→    method best_path() {
   229→        my $path = $self->path();
   230→        return $path->[0];
   231→    }
   232→
   233→    method validate_complete_parse($input_length) {
   234→        my $node = $self->sppf_node();
   235→        return $node->start_pos() == 0 && $node->end_pos() == $input_length;
   236→    }
   237→}
   238→
   239→class Chalk::ParseForest {
   240→    field %symbol_nodes;
   241→    field %terminal_nodes;
   242→
   243→    method get_or_create_symbol_node( $symbol, $start_pos, $end_pos ) {
   244→        my $key = "$symbol|$start_pos|$end_pos";
   245→        return $symbol_nodes{$key} //= Chalk::ParseForest::SymbolNode->new(
   246→            symbol    => $symbol,
   247→            start_pos => $start_pos,
   248→            end_pos   => $end_pos
   249→        );
   250→    }
   251→
   252→    method get_or_create_terminal_node( $symbol, $start_pos, $end_pos ) {
   253→        my $key = "$symbol|$start_pos|$end_pos";
   254→        return $terminal_nodes{$key} //= Chalk::ParseForest::TerminalNode->new(
   255→            symbol    => $symbol,
   256→            start_pos => $start_pos,
   257→            end_pos   => $end_pos
   258→        );
   259→    }
   260→
   261→    method create_sequence_node( $left_node, $right_node ) {
   262→        my $start = $left_node->start_pos();
   263→        my $end = $right_node->end_pos();
   264→
   265→        my $seq_node = $self->get_or_create_symbol_node( "SEQ", $start, $end );
   266→
   267→        my $packed = Chalk::ParseForest::PackedNode->new( rule => undef );
   268→        $packed->add_child($left_node);
   269→        $packed->add_child($right_node);
   270→        $seq_node->add_packed_node($packed);  # add_packed_node handles de-duplication
   271→
   272→        return $seq_node;
   273→    }
   274→
   275→    method add_alternative( $node1, $node2 ) {
   276→        my $class = 'Chalk::ParseForest::SymbolNode';
   277→        return unless ref($node1) eq $class && ref($node2) eq $class;
   278→
   279→        # Merge all packed nodes from node2 into node1
   280→        my @nodes = $node2->packed_nodes();
   281→        for my $packed (@nodes) {
   282→            $node1->add_packed_node($packed);  # add_packed_node handles de-duplication
   283→        }
   284→    }
   285→
   286→    method nodes() {
   287→        return \%symbol_nodes;
   288→    }
   289→}
   290→
   291→# SPPFViterbi Semiring - now implemented as Composite(SPPF, Viterbi)
   292→# Provides backward compatibility while using clean separation of concerns
   293→class Chalk::Semiring::SPPFViterbiSemiring :isa(Chalk::Semiring) {
   294→    field $composite :reader;
   295→    field $sppf_semiring :reader;
   296→    field $viterbi_semiring :reader;
   297→    field $forest :reader;
   298→    field $root_element :reader;
   299→    field $mul_id :reader;
   300→    field $add_id :reader;
   301→
   302→    ADJUST {
   303→        # Create child semirings
   304→        $sppf_semiring = Chalk::Semiring::SPPF->new();
   305→        $viterbi_semiring = Chalk::Semiring::Viterbi->new();
   306→
   307→        # Create composite
   308→        $composite = Chalk::Semiring::Composite->new(
   309→            semirings => [$sppf_semiring, $viterbi_semiring]
   310→        );
   311→
   312→        # Expose forest for backward compatibility
   313→        $forest = $sppf_semiring->forest();
   314→
   315→        # Wrap identity elements
   316→        my $comp_mul_id = $composite->mul_id();
   317→        $mul_id = Chalk::Semiring::SPPFViterbiElement->new(
   318→            composite => $comp_mul_id
   319→        );
   320→
   321→        my $comp_add_id = $composite->add_id();
   322→        $add_id = Chalk::Semiring::SPPFViterbiElement->new(
   323→            composite => $comp_add_id
   324→        );
   325→
   326→        $root_element = $mul_id;  # For compatibility
   327→    }
   328→
   329→    method init_element_from_rule($rule, $start_pos = 0, $end_pos = 0) {
