     1→# ABOUTME: Composite semiring pattern for combining multiple semirings
     2→# ABOUTME: Provides delegation and composition of orthogonal semiring concerns
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→use Chalk::Base;
     7→
     8→class Chalk::Semiring::CompositeElement :isa(Chalk::Element) {
     9→    field $elements :param :reader;
    10→
    11→    method add( $other, $swap = undef ) {
    12→        # Delegate addition to each child element
    13→        my @results;
    14→        for my $i (0..$#$elements) {
    15→            push @results, $elements->[$i]->add($other->elements->[$i]);
    16→        }
    17→
    18→        return Chalk::Semiring::CompositeElement->new(
    19→            elements => \@results
    20→        );
    21→    }
    22→
    23→    method multiply( $other, $swap = undef ) {
    24→        # Delegate multiplication to each child element
    25→        my @results;
    26→        for my $i (0..$#$elements) {
    27→            push @results, $elements->[$i]->multiply($other->elements->[$i]);
    28→        }
    29→
    30→        return Chalk::Semiring::CompositeElement->new(
    31→            elements => \@results
    32→        );
    33→    }
    34→
    35→    method equals( $other, $swap = undef ) {
    36→        return 0 unless ref($other) eq ref($self);
    37→        return 0 unless scalar($elements->@*) == scalar($other->elements->@*);
    38→
    39→        # All child elements must be equal
    40→        for my $i (0..$#$elements) {
    41→            return 0 unless $elements->[$i]->equals($other->elements->[$i]);
