     1→# ABOUTME: Comonad implementation for semantic evaluation contexts
     2→# ABOUTME: Provides extract, extend, duplicate operations for context-sensitive evaluation
     3→
     4→use 5.42.0;
     5→use experimental 'class';
     6→
     7→class Chalk::EvalContext {
     8→    field $focus :param :reader;        # Current semantic value
     9→    field $children :param :reader;     # Child contexts (array ref)
    10→    field $start_pos :param :reader;    # Parse span start
    11→    field $end_pos :param :reader;      # Parse span end
    12→    field $env :param :reader;          # Environment (symbol table)
    13→    field $grammar :param :reader;      # Grammar reference
    14→    field $rule :param :reader;         # Rule being evaluated
    15→    field $forest :param :reader = undef;  # Optional shared parse forest
    16→
    17→    # Comonad operation: extract the focus value
    18→    method extract() {
    19→        return $focus;
    20→    }
    21→
    22→    # Functor operation: map a function over the focus
    23→    method fmap($f) {
    24→        return Chalk::EvalContext->new(
    25→            focus => $f->($focus),
    26→            children => $children,
    27→            start_pos => $start_pos,
    28→            end_pos => $end_pos,
    29→            env => $env,
    30→            grammar => $grammar,
    31→            rule => $rule,
    32→            forest => $forest
    33→        );
    34→    }
    35→
    36→    # Comonad operation: extend with a function
    37→    # The function receives a context and returns a new focus value
    38→    method extend($f) {
    39→        my $new_focus = $f->($self);
    40→        my @new_children = map { $_->extend($f) } $children->@*;
    41→
    42→        return Chalk::EvalContext->new(
    43→            focus => $new_focus,
    44→            children => \@new_children,
    45→            start_pos => $start_pos,
    46→            end_pos => $end_pos,
    47→            env => $env,
    48→            grammar => $grammar,
    49→            rule => $rule,
    50→            forest => $forest
    51→        );
    52→    }
    53→
    54→    # Comonad operation: duplicate context
    55→    # Returns a context whose focus is the original context
    56→    method duplicate() {
    57→        my @dup_children = map { $_->duplicate } $children->@*;
    58→
    59→        return Chalk::EvalContext->new(
    60→            focus => $self,
    61→            children => \@dup_children,
    62→            start_pos => $start_pos,
    63→            end_pos => $end_pos,
    64→            env => $env,
    65→            grammar => $grammar,
    66→            rule => $rule,
    67→            forest => $forest
    68→        );
    69→    }
    70→
    71→    # Convenience method: get extracted value of child at index
    72→    method child($index) {
    73→        return unless $index < scalar($children->@*);
    74→        return $children->[$index]->extract;
    75→    }
    76→
    77→    # Convenience method: get child context at index
    78→    method child_context($index) {
    79→        return unless $index < scalar($children->@*);
    80→        return $children->[$index];
    81→    }
    82→
    83→    # Get SPPF alternatives for the current parse position
    84→    # Returns array of packed nodes representing different parses
    85→    method alternatives() {
    86→        return () unless defined($forest);
    87→
    88→        # Get the SPPF node corresponding to this context's parse span
    89→        my $key = sprintf("%s|%d|%d",
    90→            $rule ? $rule->lhs : "UNKNOWN",
    91→            $start_pos,
    92→            $end_pos
    93→        );
    94→
    95→        my $nodes = $forest->nodes();
    96→        my $node = $nodes->{$key};
    97→        return () unless $node;
    98→
    99→        return $node->packed_nodes();
   100→    }
   101→
   102→    # Get alternatives for a specific child position
   103→    # Useful for querying different parse alternatives of a child
   104→    method child_alternatives($index) {
   105→        return () unless $index < scalar($children->@*);
   106→        my $child = $children->[$index];
   107→        return $child->alternatives() if $child->can('alternatives');
   108→        return ();
   109→    }
   110→}
   111→

