     1→#!/usr/bin/env perl
     2→# ABOUTME: Integration test for BNF semantic actions with build_chalk_grammar()
     3→# ABOUTME: Validates semantic actions can parse real BNF files
     4→
     5→use 5.42.0;
     6→use warnings;
     7→use Test::More;
     8→
     9→use lib 'lib';
    10→use Chalk::Grammar::BNF;
    11→use Chalk::Grammar;
    12→
    13→# Test 1: build_chalk_grammar() works with simple BNF
    14→{
    15→    my $bnf = "Foo -> 'bar'\n";
    16→    my $grammar = Chalk::Grammar->build_from_bnf($bnf);
    17→
    18→    ok($grammar, 'build_chalk_grammar returns result');
    19→    isa_ok($grammar, 'Chalk::Grammar', 'Result is Grammar object');
    20→
    21→    my @rules = $grammar->rules_for('Foo');
    22→    is(scalar(@rules), 1, 'Grammar has Foo rule');
    23→    is_deeply($rules[0]->rhs, ['bar'], 'Foo RHS is [bar]');
    24→}
    25→
    26→# Test 2: Works with multiple rules
    27→{
    28→    my $bnf = <<'EOF';
    29→Expr -> Term
    30→Expr -> Expr '+' Term
    31→Term -> 'number'
    32→EOF
    33→
    34→    my $grammar = Chalk::Grammar->build_from_bnf($bnf);
    35→    ok($grammar, 'Parses multiple rules');
    36→
    37→    my @expr_rules = $grammar->rules_for('Expr');
    38→    is(scalar(@expr_rules), 2, 'Expr has 2 alternatives');
    39→
    40→    my @term_rules = $grammar->rules_for('Term');
    41→    is(scalar(@term_rules), 1, 'Term has 1 rule');
    42→}
    43→
    44→# Test 3: Works with empty productions
