#!/usr/bin/env perl
# ABOUTME: Test for ambiguous parse disambiguation in assignments
# ABOUTME: Validates that Assignment.pm selects complete parses when alternatives exist

use v5.42;
use Test::More;
use Test::Deep;

use lib 'lib';
use Chalk::Grammar;
use Chalk::Parser;
use Chalk::Semiring::Semantic;
use Chalk::IR::Graph;
use Chalk::IR::Builder;

# Test 1: Parse `$i = $i - 1` and verify complete Store node
subtest 'Ambiguous assignment: $i = $i - 1' => sub {
    # This expression has two possible parses:
    # 1. $i = ($i - 1)  - Complete parse with subtraction
    # 2. ($i = $i) - 1  - Incomplete parse (treating RHS as just $i)
    #
    # The parser should choose parse #1 (complete) over #2 (incomplete)

    my $code = <<'CODE';
sub decrement($i) {
    $i = $i - 1;
    return $i;
}
CODE

    # Load Chalk grammar
    open my $fh, '<', 'grammar/chalk.bnf' or die "Cannot open grammar/chalk.bnf: $!";
    my $bnf_content = do { local $/; <$fh> };
    close $fh;

    my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program');
    ok($grammar, 'Grammar loaded');

    # Create IR builder and environment
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    # Create semantic semiring with IR builder in environment
    my $semiring = Chalk::Semiring::Semantic->new(
        env => $env,
        grammar => $grammar
    );

    # Parse with semantic evaluation
    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string($code);
    ok($result, 'Code parses successfully');
    isa_ok($result, 'Chalk::Semiring::SemanticElement', 'Result is SemanticElement');

    # The IR graph was built during parsing via semantic actions
    # Access the graph from the builder
    my $graph = $builder->graph();

    # Find the Store node for $i assignment
    my @all_nodes = values %{$graph->nodes};
    my @store_nodes = grep { $_->op eq 'Store' } @all_nodes;

    ok(scalar(@store_nodes) > 0, 'Found at least one Store node')
        or diag("Graph has " . scalar(@all_nodes) . " nodes total");

    # Find the Store node for $i (not $ctrl or other variables)
    my ($store_node) = grep {
        $_->attributes->{name} eq '$i'
    } @store_nodes;

    ok($store_node, 'Found Store node for $i') or do {
        diag("Store nodes found:");
        diag("  $_") for map { $_->attributes->{name} } @store_nodes;
    };

    # Verify the RHS value is a Subtract node (not just a Load)
    # Complete parse: $i = ($i - 1)
    # The 'value' attribute should reference a Subtract node
    my $value_ref = $store_node->attributes->{value};
    ok(defined($value_ref), 'Store has value reference');
    is($value_ref->{op}, 'NodeRef', 'Value is a node reference');

    my $value_id = $value_ref->{node_id};
    my $value_node = $graph->get_node($value_id);
    ok(defined($value_node), 'Value node exists in graph');

    # THIS IS THE KEY TEST: The value should be Subtract, not Load
    # If it's Load, then the parser chose the incomplete parse
    is($value_node->op, 'Subtract', 'Value is Subtract operation (complete parse)')
        or diag("Got op: " . $value_node->op . " (incomplete parse - FAIL)");

    # If we got Subtract, verify its operands
    if ($value_node->op eq 'Subtract') {
        my $left_ref = $value_node->attributes->{left};
        ok(defined($left_ref), 'Subtract has left operand');

        my $right_ref = $value_node->attributes->{right};
        ok(defined($right_ref), 'Subtract has right operand');

        # Left should be Load of $i
        my $left_id = $left_ref->{node_id};
        my $left_node = $graph->get_node($left_id);
        is($left_node->op, 'Load', 'Left operand is Load');
        is($left_node->attributes->{name}, '$i', 'Loading from $i');

        # Right should be Constant 1
        my $right_id = $right_ref->{node_id};
        my $right_node = $graph->get_node($right_id);
        is($right_node->op, 'Constant', 'Right operand is Constant');
        is($right_node->attributes->{value}, 1, 'Constant value is 1');
    }
};

# Test 2: Simple unambiguous assignment (control test)
subtest 'Unambiguous assignment: $x = 5' => sub {
    my $code = <<'CODE';
sub assign($x) {
    $x = 5;
    return $x;
}
CODE

    # Load grammar
    open my $fh, '<', 'grammar/chalk.bnf' or die "Cannot open grammar/chalk.bnf: $!";
    my $bnf_content = do { local $/; <$fh> };
    close $fh;

    my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program');

    # Create IR infrastructure
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    my $semiring = Chalk::Semiring::Semantic->new(
        env => $env,
        grammar => $grammar
    );

    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string($code);
    ok($result, 'Unambiguous code parses');

    # Access the graph from builder
    my $graph = $builder->graph();

    # Find Store node for $x
    my @store_nodes = grep { $_->op eq 'Store' } values %{$graph->nodes};
    my ($store) = grep { $_->attributes->{name} eq '$x' } @store_nodes;

    ok($store, 'Found Store for $x');

    # Value should be Constant 5
    my $value_ref = $store->attributes->{value};
    my $value_id = $value_ref->{node_id};
    my $value_node = $graph->get_node($value_id);

    is($value_node->op, 'Constant', 'Value is Constant');
    is($value_node->attributes->{value}, 5, 'Constant is 5');
};

done_testing();

