# Test 1: Parse `$i = $i - 1` and verify complete Store node
subtest 'Ambiguous assignment: $i = $i - 1' => sub {
    # This expression has two possible parses:
    # 1. $i = ($i - 1)  - Complete parse with subtraction
    # 2. ($i = $i) - 1  - Incomplete parse (treating RHS as just $i)
    #
    # The parser should choose parse #1 (complete) over #2 (incomplete)

    my $code = <<'CODE';
sub decrement($i) {
    $i = $i - 1;
    return $i;
}
CODE

    # Load Chalk grammar
    open my $fh, '<', 'grammar/chalk.bnf' or die "Cannot open grammar/chalk.bnf: $!";
    my $bnf_content = do { local $/; <$fh> };
    close $fh;

    my $grammar = Chalk::Grammar->build_from_bnf($bnf_content, 'Program');
    ok($grammar, 'Grammar loaded');

    # Create IR builder and environment
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    # Create semantic semiring with IR builder in environment
    my $semiring = Chalk::Semiring::Semantic->new(
        env => $env,
        grammar => $grammar
    );

    # Parse with semantic evaluation
    my $parser = Chalk::Parser->new(
        grammar => $grammar,
        semiring => $semiring
    );

    my $result = $parser->parse_string($code);
    ok($result, 'Code parses successfully');
    isa_ok($result, 'Chalk::Semiring::SemanticElement', 'Result is SemanticElement');

    # The IR graph was built during parsing via semantic actions
    # Access the graph from the builder
    my $graph = $builder->graph();

    # Find the Store node for $i assignment
    my @all_nodes = values %{$graph->nodes};
    my @store_nodes = grep { $_->op eq 'Store' } @all_nodes;

    ok(scalar(@store_nodes) > 0, 'Found at least one Store node')
        or diag("Graph has " . scalar(@all_nodes) . " nodes total");

    # Find the Store node for $i (not $ctrl or other variables)
    my ($store_node) = grep {
        $_->attributes->{name} eq '$i'
    } @store_nodes;

    ok($store_node, 'Found Store node for $i') or do {
        diag("Store nodes found:");
        diag("  $_") for map { $_->attributes->{name} } @store_nodes;
    };

    # Verify the RHS value is a Subtract node (not just a Load)
    # Complete parse: $i = ($i - 1)
    # The 'value' attribute should reference a Subtract node
    my $value_ref = $store_node->attributes->{value};
