     4→use 5.42.0;
     5→use experimental 'class';
     6→use Scalar::Util qw(blessed);
     7→
     8→class Chalk::Grammar::Chalk::Rule::Assignment :isa(Chalk::GrammarRule) {
     9→    method evaluate($context) {
    10→        # Assignment -> Ternary (pass-through)
    11→        # Assignment -> Ternary WS_OPT '=' WS_OPT Assignment
    12→        # Assignment -> Ternary WS_OPT %ASSIGN_OP% WS_OPT Assignment (TODO: compound assignment)
    13→
    14→        my @children = $context->children->@*;
    15→        my $builder = $context->env->{ir_builder};
    16→
    17→        # Check if this is an assignment operation (has '=' operator)
    18→        my $has_assignment = 0;
    19→        my $equals_index = -1;
    20→        for my $i (0..$#children) {
    21→            my $child = $children[$i]->extract;
    22→            if (defined $child && !ref($child) && $child eq '=') {
    23→                $has_assignment = 1;
    24→                $equals_index = $i;
    25→                last;
    26→            }
    27→        }
    28→
    29→        # If no '=' operator, just pass through the Ternary child
    30→        return $context->child(0) unless $has_assignment;
    31→
    32→        # We have an assignment: Ternary = Assignment
    33→        return $context->child(0) unless $builder;
    34→
    35→        # Get left side (variable being assigned to)
    36→        my $lhs = $context->child(0);
    37→
    38→        # Extract variable name from lhs
    39→        # Three possible cases:
    40→        # 1. Variable metadata hash (from ScalarVar before Primary processes it)
    41→        # 2. Load node (from regular variables after Primary)
    42→        # 3. Proj node (from parameters - build_load_node returns Proj directly for params)
    43→        my $var_name;
    44→        if (ref($lhs) eq 'HASH' && $lhs->{type} eq 'scalar_var') {
    45→            # Case 1: Variable metadata
    46→            $var_name = $lhs->{name};
    47→        } elsif (blessed($lhs) && $lhs->can('op')) {
    48→            if ($lhs->op eq 'Load') {
    49→                # Case 2: Load node from regular variable
    50→                $var_name = $lhs->attributes->{name};
    51→            } elsif ($lhs->op eq 'Proj') {
    52→                # Case 3: Proj node from parameter
    53→                $var_name = $lhs->attributes->{label};
    54→            } else {
    55→                # Unsupported node type for assignment target
    56→                return $context->child(0);
    57→            }
    58→        } else {
    59→            # Can't handle this lhs type for assignment
    60→            return $context->child(0);
    61→        }
    62→
    63→        # Get right side (value to assign) - after '=' + WS_OPT, which is equals_index + 2
    64→        my $rhs_index = $equals_index + 2;
    65→        my $rhs = $context->child($rhs_index);
    66→
    67→        # Validate we got an IR node for the value
    68→        return $context->child(0) unless (blessed($rhs) && $rhs->can('id'));
    69→
    70→        # Create Store node with placeholder control
    71→        # Parent rule (Block, ConditionalStatement, WhileStatement) will wire actual control
    72→        #
    73→        # NOTE: SPPF may create multiple parse trees for complex expressions like "$i = $i - 1"
    74→        # Both parses create Store nodes in the graph, semiring picks one for the parse tree.
    75→        # Currently semiring may pick incomplete parse (rhs=$i instead of rhs=$i-1).
    76→        # This is expected SPPF behavior - will need optimization pass to detect/fix later.
    77→        return $builder->build_store_node($var_name, $rhs, '__CONTROL_PLACEHOLDER__');
