+        if ($node->op eq 'Subtract' || $node->op eq 'Add' || $node->op eq 'Multiply') {
+            if (my $left = $node->attributes->{left}) {
+                my $left_node = $graph->get_node($left->{node_id});
+                $count += count_ir_nodes($left_node, $graph);
