     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);;
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    field $graph :reader;
    13→    field $scope :reader;
    14→    field $node_counter :reader = 0;
    15→    field $current_control :reader;  # Current control flow node
    16→
    17→    ADJUST {
    18→        $graph = Chalk::IR::Graph->new();
    19→        $scope = Chalk::IR::Scope->new();
    20→    }
    21→
    22→    # Generate unique node ID
    23→    method next_node_id() {
    24→        my $id = "node_$node_counter";
    25→        $node_counter++;
    26→        return $id;
    27→    }
    28→
    29→    # Set current control flow node
    30→    method set_control($ctrl) {
    31→        $current_control = $ctrl;
    32→    }
    33→
    34→    # Create Start node for a function/method
    35→    method build_start_node($function_name = 'main', $params = []) {
    36→        my $start = Chalk::IR::Node->new(
    37→            id => $self->next_node_id(),
    38→            op => 'Start',
    39→            inputs => [],
    40→            attributes => {
    41→                function => $function_name,
    42→                params => $params
    43→            }
    44→        );
    45→        $graph->add_node($start);
    46→        $self->set_control($start->id);
    47→
    48→        # Create Proj nodes for each parameter and register in scope
    49→        for my $i (0..$#{$params}) {
    50→            my $param_name = $params->[$i];
    51→            my $proj = $self->build_proj_node($start, $i, $param_name);
    52→            # Register parameter Proj in scope so lookups return it directly
    53→            $scope->define($param_name, $proj->id);
    54→        }
    55→
    56→        return $start;
    57→    }
    58→
    59→    # Create Constant node
    60→    method build_constant_node($value, $type = 'Int') {
    61→        my $constant = Chalk::IR::Node->new(
    62→            id => $self->next_node_id(),
    63→            op => 'Constant',
    64→            inputs => [$current_control],
    65→            attributes => { value => $value, type => $type }
    66→        );
    67→        $graph->add_node($constant);
    68→        return $constant;
    69→    }
    70→
    71→    # Create Return node
    72→    # If $control is undef, uses current_control. Otherwise uses provided control.
    73→    method build_return_node($value_node, $control = undef) {
    74→        # Debug: check what we received
    75→        my $ref_type = ref($value_node) || 'SCALAR';
    76→        unless ($ref_type && $ref_type =~ /^Chalk::IR::Node/) {
    77→            use Data::Dumper;
    78→            warn "build_return_node received non-node: $ref_type\n";
    79→            warn "Value: " . Dumper($value_node);
    80→            return undef;
    81→        }
    82→
    83→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
    84→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
    85→
    86→        my $return = Chalk::IR::Node->new(
    87→            id => $self->next_node_id(),
    88→            op => 'Return',
    89→            inputs => [$ctrl, $value_node->id],
    90→            attributes => {}
    91→        );
    92→        $graph->add_node($return);
    93→        return $return;
    94→    }
    95→
    96→    # Set control input for an existing node
    97→    method set_node_control($node, $control_id) {
    98→        my $inputs = $node->inputs;
    99→        $inputs->[0] = $control_id;  # Control is always first input
   100→    }
   101→
   102→    # Create arithmetic operation nodes
   103→    method build_add_node($left_node, $right_node) {
   104→        my $add = Chalk::IR::Node->new(
   105→            id => $self->next_node_id(),
   106→            op => 'Add',
   107→            inputs => [$current_control, $left_node->id, $right_node->id],
   108→            attributes => {
   109→                left => { op => 'NodeRef', node_id => $left_node->id },
   110→                right => { op => 'NodeRef', node_id => $right_node->id }
   111→            }
   112→        );
   113→        $graph->add_node($add);
   114→        return $add;
   115→    }
   116→
   117→    method build_multiply_node($left_node, $right_node) {
