   119→            id => $self->next_node_id(),
   120→            op => 'Multiply',
   121→            inputs => [$current_control, $left_node->id, $right_node->id],
   122→            attributes => {
   123→                left => { op => 'NodeRef', node_id => $left_node->id },
   124→                right => { op => 'NodeRef', node_id => $right_node->id }
   125→            }
   126→        );
