    18→subtest 'Break statement basic structure' => sub {
    19→    # while (true) { break; }
    20→    my $graph = Chalk::IR::Graph->new();
    21→
    22→    my $start = Chalk::IR::Node->new(
    23→        id => 1,
    24→        op => 'Start',
    25→        inputs => [],
    26→        attributes => {},
    27→    );
    28→    $graph->add_node($start);
    29→
    30→    my $loop = Chalk::IR::Node->new(
    31→        id => 2,
    32→        op => 'Loop',
    33→        inputs => [$start->id],
    34→        attributes => {},
    35→    );
    36→    $graph->add_node($loop);
    37→
    38→    # Break creates a Region with loop exit and break paths
    39→    my $break_region = Chalk::IR::Node->new(
    40→        id => 3,
    41→        op => 'Region',
    42→        inputs => [$loop->id],  # Break path will be added
    43→        attributes => {},
    44→    );
    45→    $graph->add_node($break_region);
    46→
    47→    # Loop backedge goes nowhere (break exits immediately)
    48→    # Break exits to region
    49→
    50→    my $return_node = Chalk::IR::Node->new(
    51→        id => 4,
    52→        op => 'Return',
    53→        inputs => [$break_region->id, 0],
    54→        attributes => {},
    55→    );
    56→    $graph->add_node($return_node);
    57→
    58→    is scalar($loop->inputs->@*), 1, 'Loop has only entry (no backedge due to break)';
    59→    ok $break_region, 'Break creates exit region';
    60→};
    61→
    62→subtest 'Break with condition: while(i < 10) { if(i == 5) break; i++; }' => sub {
    63→    my $graph = Chalk::IR::Graph->new();
    64→
    65→    my $start = Chalk::IR::Node->new(
    66→        id => 1,
    67→        op => 'Start',
    68→        inputs => [],
    69→        attributes => {},
    70→    );
    71→    $graph->add_node($start);
    72→
    73→    my $const_0 = Chalk::IR::Node->new(
    74→        id => 2,
    75→        op => 'Constant',
    76→        inputs => [],
    77→        attributes => { value => 0 },
    78→    );
    79→    $graph->add_node($const_0);
    80→
    81→    my $loop = Chalk::IR::Node->new(
    82→        id => 3,
    83→        op => 'Loop',
    84→        inputs => [$start->id],
    85→        attributes => {},
    86→    );
    87→    $graph->add_node($loop);
    88→
    89→    my $phi_i = Chalk::IR::Node->new(
    90→        id => 4,
    91→        op => 'Phi',
    92→        inputs => [$loop->id, $const_0->id],
    93→        attributes => {},
    94→    );
