use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use Chalk::Parser;
use Chalk::IR::Builder;
use Chalk::Semiring::Semantic;

subtest 'Parse loop with single modified variable' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 10) {
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new();
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_single_phi');

    my $result = $parser->parse($code, env => $env);

    ok $result, 'Loop with modified variable parses successfully';

    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 1, 'One Loop node created';

    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 1, 'At least one Phi node for loop-carried variable';

    # Phi should have: control (Loop), initial value, loop value
    if (@phi_nodes) {
        my $phi = $phi_nodes[0];
        is scalar($phi->inputs->@*), 3, 'Phi has control, initial value, and loop value';
    }
};

