    my $graph = $builder->graph;
    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 2, 'Multiple Phi nodes for multiple loop-carried variables';

    # Each phi should be properly wired
    for my $phi (@phi_nodes) {
        is scalar($phi->inputs->@*), 3, 'Each Phi has control, initial value, and loop value';
    }
};

