    my $code = q{
        my $count = 0;
        my $i = 0;
        while ($i < 10) {
            if ($i > 5) {
                $count = $count + 1;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new();
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_conditional_phi');

    my $result = $parser->parse($code, env => $env);

    ok $result, 'Loop with conditional modification parses successfully';

    my $graph = $builder->graph;
    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 2, 'Phi nodes for conditionally modified variables';

    # Variables modified conditionally still need phi nodes
    # The phi merges the modified and unmodified paths
};

subtest 'Parse nested loops with separate phis' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 5) {
            my $j = 0;
            while ($j < 3) {
                $j = $j + 1;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new();
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_nested_phis');

    my $result = $parser->parse($code, env => $env);

    ok $result, 'Nested loops parse successfully';

    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 2, 'Two Loop nodes for nested structure';

    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 2, 'Phi nodes for each loop variable';
};

subtest 'Parse loop with break and phi values' => sub {
    my $code = q{
        my $result = 0;
        my $i = 0;
        while ($i < 10) {
            if ($i == 5) {
                $result = $i;
                break;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new();
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_break_phi');

    my $result = $parser->parse($code, env => $env);

    ok $result, 'Loop with break and phi values parses successfully';

    my $graph = $builder->graph;
    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 2, 'Phi nodes for loop variables';

    # Break exit should merge phi values from break path and normal exit
    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 1, 'Region merges break and normal exit paths';
};

subtest 'Parse loop with continue and phi values' => sub {
    my $code = q{
        my $sum = 0;
        my $i = 0;
        while ($i < 10) {
            if ($i == 5) {
                $i = $i + 1;
                continue;
            }
            $sum = $sum + $i;
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new();
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_continue_phi');

    my $result = $parser->parse($code, env => $env);

    ok $result, 'Loop with continue and phi values parses successfully';

    my $graph = $builder->graph;
    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 2, 'Phi nodes for loop-carried variables';

    # Continue creates additional backedge to loop
    # Phi should merge values from both continue and normal paths
};

subtest 'Parse complex accumulator pattern' => sub {
    my $code = q{
        my $sum = 0;
        my $prod = 1;
        my $i = 1;
        while ($i < 5) {
            $sum = $sum + $i;
            $prod = $prod * $i;
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new();
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_accumulator');

    my $result = $parser->parse($code, env => $env);

    ok $result, 'Complex accumulator pattern parses successfully';

    my $graph = $builder->graph;
    my @phi_nodes = grep { $_->op eq 'Phi' } values $graph->nodes->%*;
    ok scalar(@phi_nodes) >= 3, 'Phi nodes for all three loop variables (sum, prod, i)';

    # Verify Store nodes for assignments
    my @store_nodes = grep { $_->op eq 'Store' } values $graph->nodes->%*;
    ok scalar(@store_nodes) >= 6, 'Store nodes for initial assignments and loop updates';
};

