#!/usr/bin/env perl
# ABOUTME: Integration tests for parsing break/continue statements
# ABOUTME: Validates that Chalk grammar parses loop control flow and generates correct IR

use 5.42.0;
use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use Chalk::Parser;
use Chalk::Grammar;
use Chalk::IR::Builder;
use Chalk::Semiring::Semantic;

# Load the chalk.bnf grammar
open my $grammar_fh, "<:utf8", "$RealBin/../../grammar/chalk.bnf" or die $!;
my $bnf_content = do { local $/; <$grammar_fh> };
close $grammar_fh;

my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, "Program");

subtest 'Parse simple break statement' => sub {
    my $code = q{
        my $i = 10;
        while ($i > 0) {
            break;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    # Start IR generation
    $builder->build_start_node('test_break');

    my $result = $parser->parse_string($code);

    ok $result, 'Break statement parses successfully';

    # Verify IR structure
    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 1, 'One Loop node created';

    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 1, 'At least one Region node for break exit';

    # Loop should have entry but minimal backedge due to break
    my $loop = $loop_nodes[0];
    ok $loop->inputs->[0], 'Loop has entry control';
};

subtest 'Parse conditional break' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 10) {
            if ($i == 5) {
                break;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_conditional_break');

    my $result = $parser->parse_string($code);

    ok $result, 'Conditional break parses successfully';

    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 1, 'One Loop node created';

    my @if_nodes = grep { $_->op eq 'If' } values $graph->nodes->%*;
    ok scalar(@if_nodes) >= 2, 'Multiple If nodes (loop condition + break condition)';

    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 1, 'Region nodes for control flow merging';
};

subtest 'Parse simple continue statement' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 10) {
            if ($i == 5) {
                $i = $i + 1;
                continue;
            }
            $i = $i + 2;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_continue');

    my $result = $parser->parse_string($code);

    ok $result, 'Continue statement parses successfully';

    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 1, 'One Loop node created';

    # Continue should merge back to loop via Region
    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 1, 'Region nodes for continue merging';
};

subtest 'Parse break and continue together' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 100) {
            if ($i == 50) {
                break;
            }
            if ($i == 25) {
                $i = $i + 1;
                continue;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_break_and_continue');

    my $result = $parser->parse_string($code);

    ok $result, 'Break and continue together parse successfully';

    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 1, 'One Loop node created';

    my @if_nodes = grep { $_->op eq 'If' } values $graph->nodes->%*;
    ok scalar(@if_nodes) >= 3, 'Multiple If nodes (loop + break + continue conditions)';

    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 2, 'Multiple Region nodes for complex control flow';
};

subtest 'Parse nested loops with break' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 5) {
            my $j = 0;
            while ($j < 3) {
                if ($j == 2) {
                    break;
                }
                $j = $j + 1;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_nested_break');

    my $result = $parser->parse_string($code);

    ok $result, 'Nested loops with break parse successfully';

    my $graph = $builder->graph;
    my @loop_nodes = grep { $_->op eq 'Loop' } values $graph->nodes->%*;
    is scalar(@loop_nodes), 2, 'Two Loop nodes for nested loops';

    # Inner break should only affect inner loop
    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 2, 'Region nodes for both loop exits';
};

subtest 'Parse multiple break exits' => sub {
    my $code = q{
        my $i = 0;
        while ($i < 100) {
            if ($i == 10) {
                break;
            }
            if ($i == 20) {
                break;
            }
            $i = $i + 1;
        }
    };

    my $parser = Chalk::Parser->new(grammar => $chalk_grammar);
    my $builder = Chalk::IR::Builder->new();
    my $env = { ir_builder => $builder };

    $builder->build_start_node('test_multiple_breaks');

    my $result = $parser->parse_string($code);

    ok $result, 'Multiple break exits parse successfully';

    my $graph = $builder->graph;
    my @region_nodes = grep { $_->op eq 'Region' } values $graph->nodes->%*;
    ok scalar(@region_nodes) >= 1, 'Region merges multiple break paths';
};

